[Form]
public class NDXItemValidityTest extends FormRun implements INDX_ItemValidityTest
{
    NDXValidityCheckType checkType = NDXValidityCheckType::QuotationNumber;
}

public void init()
{
    element.args().record(null);
    super();
}

public void setMessage(NDXValidityMessage _message)
{
    switch(checkType)
    {
        case NDXValidityCheckType::QuotationNumber:
            seValidityMessage.text(_message);
            break;
        case NDXValidityCheckType::SalesNumber:
            seValidityMessage2.text(_message);
            break;
    }
}

public void setMessageAll(NDXValidityMessage _message)
{
    switch(checkType)
    {
        case NDXValidityCheckType::QuotationNumber:
            seValidityMessageAll.text(_message);
            break;
        case NDXValidityCheckType::SalesNumber:
            seValidityMessageAll2.text(_message);
            break;
    }
}

/// <summary>
/// Sets the correct instance of a test object
/// </summary>
private Args setTestObject(NDXValidityCheckType _checkType = NDXValidityCheckType::Quotation)
{
    Args args = new Args();

    NDX_ItemValidityObject testObject;

    switch(_checkType)
    {
        case NDXValidityCheckType::QuotationNumber:
            testObject = NDX_ItemValidityObjectQuotation::construct(Check_QuotationId.text(), Check_KCS_KBVBuildingProjectID.text());
            testObject.parmCheck_Date(Check_Date.dateValue());
            testObject.parmCheck_ItemId(Check_ItemId.text());
            testObject.parmCheck_CustAccount(Check_CustAccount.text());
            testObject.parmCheck_ChainId(Check_ChainId.text());
            break;
        case NDXValidityCheckType::SalesNumber:
            testObject = NDX_ItemValidityObjectSales::construct(Check_SalesId.text(), Check_QuotationId2.text());
            testObject.parmCheck_Date(Check_Date2.dateValue());
            testObject.parmCheck_ItemId(Check_ItemId2.text());
            testObject.parmCheck_CustAccount(Check_CustAccount2.text());
            testObject.parmCheck_ChainId(Check_ChainId2.text());
            break;
    }

    args.object(testObject);
    args.caller(this);

    return args;
}

